import os
for r,ds,fs in os.walk('studies'):
 for f in fs: print(os.path.join(r,f))

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as h:
  for l in h:
   if l.startswith('!Sample_') or l.startswith(('!Series_summary','!Series_overall_design')): print(l.rstrip())

import gzip,glob,csv
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 rows=[next(csv.reader([l],delimiter='\t')) for l in gzip.open(f,'rt') if l.startswith(('!Sample_title','!Sample_geo_accession','!Sample_characteristics','!Sample_source_name'))]
 for vals in zip(*[r[1:] for r in rows]):print(' | '.join(vals))
 for l in gzip.open(f,'rt'):
  if l.startswith(('!Series_overall_design','!Sample_treatment_protocol','!Sample_growth_protocol')):
   row=next(csv.reader([l],delimiter='\t'));print(row[0],set(row[1:]))

import gzip,glob,csv,collections
for f in sorted(glob.glob('studies/data/raw/*series*'))[1:]:
 print('\nFILE',f)
 for l in gzip.open(f,'rt'):
  if l.startswith(('!Sample_title','!Sample_characteristics','!Series_overall_design','!Sample_treatment_protocol','!Sample_growth_protocol','!Sample_extract_protocol')):
   r=next(csv.reader([l],delimiter='\t'));print(r[0],dict(collections.Counter(r[1:])))

